# =============================================================================
# Chapter 6 figures: The One-Way ANOVA
#
# Run from the project root:
#   Rscript r_code/figures/chapter_06.R
#
# Figures 6.1, 6.3, 6.4, 6.5, 6.6, and 6.7 use hsb.csv. Figure 6.2 is
# illustrative and uses simulated residuals. Captions and alt text live here,
# next to the code. figures/chapter_06/figures.yml is generated by
# save_book_fig(); do not edit it by hand.
# =============================================================================

source("r_code/figures/_book_figs.R")

suppressPackageStartupMessages({
  library(ggplot2)
  library(readr)
  library(dplyr)
})

assert_book_font()

# ---- Data -------------------------------------------------------------------

hsb <- read_csv("data/hsb.csv", show_col_types = FALSE)
hsb$prog <- factor(
  hsb$prog, levels = c("general", "academic", "vocational")
)

write_model <- aov(write ~ prog, data = hsb)
residuals_df <- data.frame(residual = residuals(write_model))
res_sd <- sd(residuals_df$residual)
n_res <- nrow(residuals_df)
bin_width <- 2.5

group_means <- hsb %>%
  group_by(prog) %>%
  summarise(mean_write = mean(write), .groups = "drop")

# ---- Shared plots -----------------------------------------------------------

# The pooled-residual histogram is used twice: once as a concept example in
# Section 6.7 and once as the actual diagnostic in Section 6.9.
make_residual_hist <- function() {
  ggplot(residuals_df, aes(x = residual)) +
    geom_histogram(
      aes(y = after_stat(count)), binwidth = bin_width, boundary = 0,
      fill = book_palette[["sky_blue"]], colour = BOOK_INK, linewidth = 0.3
    ) +
    stat_function(
      fun = function(x) dnorm(x, mean = 0, sd = res_sd) * n_res * bin_width,
      colour = book_palette[["vermillion"]], linewidth = 0.9
    ) +
    geom_vline(
      xintercept = 0, linetype = "dashed", colour = BOOK_INK, linewidth = 0.4
    ) +
    annotate(
      "text", x = 13, y = 8.5,
      label = "Normal curve", hjust = 0, size = 3,
      colour = book_palette[["vermillion"]]
    ) +
    scale_x_continuous(breaks = seq(-20, 20, 10)) +
    scale_y_continuous(expand = expansion(mult = c(0, 0.08))) +
    labs(
      x = "Residual (writing score minus group mean)",
      y = "Number of students"
    ) +
    book_theme()
}

# The jitter plot is also used twice: once for the equal-variances explanation
# and once for the full diagnostic in the guided analysis.
make_jitter_plot <- function() {
  ggplot(hsb, aes(x = prog, y = write, colour = prog, shape = prog)) +
    geom_jitter(width = 0.14, height = 0, alpha = 0.55, size = 1.7) +
    geom_point(
      data = group_means, aes(x = prog, y = mean_write),
      inherit.aes = FALSE, shape = 18, size = 3.2, colour = BOOK_INK
    ) +
    scale_colour_manual(
      values = c(
        general = book_palette[["blue"]],
        academic = book_palette[["vermillion"]],
        vocational = book_palette[["bluish_green"]]
      ),
      name = "Program track"
    ) +
    scale_shape_manual(
      values = c(general = 16, academic = 17, vocational = 15),
      name = "Program track"
    ) +
    scale_y_continuous(breaks = seq(30, 70, 10)) +
    labs(x = "Program track", y = "Standardized writing score") +
    book_theme()
}

p61 <- make_residual_hist()
p63 <- make_jitter_plot()

# ---- Figure 6.1: pooled residuals, concept example -------------------------

save_book_fig(
  p61,
  chapter = 6, id = "6.1", type = "hist",
  slug = "residuals_histogram_concept",
  caption = paste(
    "Distribution of the pooled residuals from the one-way ANOVA of writing",
    "scores by program track. The residuals are centered at zero and roughly",
    "bell-shaped, with a mild left tail. The smooth curve marks a normal",
    "distribution with the same mean and standard deviation."
  ),
  alt = paste(
    "Histogram of the pooled ANOVA residuals, centered near zero with a",
    "roughly bell-shaped distribution and a mild left tail. A smooth normal",
    "curve is overlaid, and a dashed vertical line marks zero."
  ),
  author_note = paste(
    "This is the actual residual distribution from aov(write ~ prog), not a",
    "generic illustration. The mild left tail comes from the 31-point writing",
    "score in the academic track."
  )
)

# ---- Figure 6.2: normal probability plot examples -------------------------

set.seed(2026)
n_sim <- 200
qq_examples <- rbind(
  data.frame(panel = "Normal", value = as.numeric(scale(rnorm(n_sim)))),
  data.frame(panel = "Skewed", value = as.numeric(scale(rexp(n_sim)))),
  data.frame(
    panel = "Heavy tails",
    value = as.numeric(scale(rt(n_sim, df = 3)))
  )
)
qq_examples$panel <- factor(
  qq_examples$panel, levels = c("Normal", "Skewed", "Heavy tails")
)

p62 <- ggplot(qq_examples, aes(sample = value)) +
  stat_qq(colour = book_palette[["blue"]], size = 1.4, alpha = 0.7) +
  stat_qq_line(colour = BOOK_INK, linetype = "dashed", linewidth = 0.5) +
  facet_wrap(~ panel, nrow = 1) +
  labs(
    x = "Theoretical normal quantile",
    y = "Sample quantile (standardized)"
  ) +
  book_theme()

save_book_fig(
  p62,
  chapter = 6, id = "6.2", type = "scatter",
  slug = "qq_diagnostic_examples",
  caption = paste(
    "Simulated normal probability plots for three residual patterns. In the",
    "normal panel, points follow the dashed line. In the skewed panel, the",
    "points hook away at the upper end. In the heavy-tails panel, the points",
    "form an S-curve across the line."
  ),
  alt = paste(
    "Three side-by-side normal probability plots with a dashed diagonal line.",
    "The normal panel shows points hugging the line. The skewed panel shows",
    "points curving upward at the top. The heavy-tails panel shows points below",
    "the line at the low end and above it at the high end, forming an S-shape."
  ),
  width = 6.5, height = 3.4,
  author_note = paste(
    "Simulated residuals, not the hsb.csv data. Normal uses rnorm, skewed",
    "uses rexp, and heavy tails uses rt with 3 degrees of freedom."
  )
)

# ---- Figure 6.3: jitter plot for equal variances ---------------------------

save_book_fig(
  p63,
  chapter = 6, id = "6.3", type = "scatter",
  slug = "writing_jitter_equal_variances",
  caption = paste(
    "Jitter plot of writing scores by program track. Each dot is one student,",
    "and black diamonds mark the group means. The vertical spread is similar",
    "across the three tracks, which supports the equal variances assumption."
  ),
  alt = paste(
    "Jitter plot of writing scores for the general, academic, and vocational",
    "tracks. Each dot is a student, and black diamonds mark the group means.",
    "The academic track sits higher, but the vertical spread of dots is similar",
    "across all three columns."
  )
)

# ---- Figure 6.4: side-by-side boxplot --------------------------------------

p64 <- ggplot(hsb, aes(x = prog, y = write, fill = prog)) +
  geom_boxplot(
    width = 0.6, colour = BOOK_INK, linewidth = 0.4,
    outlier.shape = 21, outlier.colour = BOOK_INK,
    outlier.fill = BOOK_INK, outlier.size = 2
  ) +
  scale_fill_manual(
    values = c(
      general = book_palette[["blue"]],
      academic = book_palette[["vermillion"]],
      vocational = book_palette[["bluish_green"]]
    ),
    name = "Program track"
  ) +
  scale_y_continuous(breaks = seq(30, 70, 10)) +
  labs(x = "Program track", y = "Standardized writing score") +
  book_theme()

save_book_fig(
  p64,
  chapter = 6, id = "6.4", type = "box",
  slug = "writing_boxplot_by_program",
  caption = paste(
    "Side-by-side boxplots of standardized writing scores by program track.",
    "The line inside each box is the median, the box is the interquartile",
    "range, and the whiskers extend to the non-outlying data. The academic",
    "track has the highest median and the narrowest box, with one low outlier."
