  ),
  direct_labels = TRUE,
  author_note = paste(
    "The academic track's low outlier is the 31-point writing score."
  )
)

# ---- Figure 6.5: pooled residuals, guided analysis -------------------------

save_book_fig(
  p61,
  chapter = 6, id = "6.5", type = "hist",
  slug = "residuals_histogram_analysis",
  caption = paste(
    "Distribution of the pooled residuals from the one-way ANOVA in the",
    "guided analysis. The shape is mostly bell-shaped with a mild left tail,",
    "consistent with the lowest writing score in the academic track. The smooth",
    "curve marks a normal distribution with the same mean and standard",
    "deviation."
  ),
  alt = paste(
    "Histogram of the pooled ANOVA residuals, mostly bell-shaped and centered",
    "near zero, with a mild left tail. A smooth normal curve is overlaid, and a",
    "dashed vertical line marks zero."
  ),
  author_note = paste(
    "The mild left tail comes from the 31-point writing score in the academic",
