# ---- Figure 6.6: normal Q-Q plot of residuals ------------------------------

p66 <- ggplot(residuals_df, aes(sample = residual)) +
  stat_qq(colour = book_palette[["blue"]], size = 1.7, alpha = 0.75) +
  stat_qq_line(colour = BOOK_INK, linetype = "dashed", linewidth = 0.55) +
  labs(
    x = "Theoretical normal quantile",
    y = "Sample quantile (residual)"
  ) +
  book_theme()

save_book_fig(
  p66,
  chapter = 6, id = "6.6", type = "scatter",
  slug = "residuals_qq_analysis",
  caption = paste(
    "Normal Q-Q plot of the pooled ANOVA residuals. Points close to the",
    "dashed line are consistent with a normal distribution. The points follow",
    "the line closely, with a small dip in the lower tail from the lowest",
    "writing score."
  ),
  alt = paste(
    "Normal Q-Q plot of the pooled residuals. Most points hug the dashed",
    "diagonal reference line, with a small dip below the line at the lower end.",
    "There is no sharp hook or S-curve."
  ),
  author_note = paste(
    "The lower-tail dip reflects the 31-point writing score; the rest of the",
    "points follow the line."
  )
)

# ---- Figure 6.7: jitter plot for the guided analysis -----------------------

save_book_fig(
  p63,
  chapter = 6, id = "6.7", type = "scatter",
  slug = "writing_jitter_analysis",
  caption = paste(
    "Jitter plot of writing scores for the three program tracks in the guided",
    "analysis. The academic track sits higher, but the full vertical spread of",
    "scores is similar across groups. Black diamonds mark the group means."
  ),
  alt = paste(
    "Jitter plot of writing scores for the three program tracks. The academic",
